// The access pages, /login/, /login/enrol/, and /tools/ (login/**/index.html and tools/index.html, generated by scripts/pages.ts). #root's data-page
// says which one. Same global styles and service worker start as the home page (src/main.tsx).
import './styles/reset.css'
import './styles/fonts.css'
import './styles/base.css'

import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { EnrolPage } from './login/EnrolPage'
import { LoginPage } from './login/LoginPage'
import { ToolsPage } from './login/ToolsPage'
import { startServiceWorker } from './telemetry/serviceWorker'

startServiceWorker()

const root = document.getElementById('root')
if (!root) throw new Error('Missing #root element')

const PAGES = { login: LoginPage, enrol: EnrolPage, tools: ToolsPage }
const Page = PAGES[root.dataset.page as keyof typeof PAGES] ?? LoginPage

createRoot(root).render(
  <StrictMode>
    <Page />
  </StrictMode>,
)
